#include <stdio.h>
int main(int argc, char *argv[]) {
    if (argc != 2) return 1;
    FILE *input = fopen(argv[1], "r");
    if (input == NULL) return 1;
    unsigned long count = 0;
    int ch;
    int failed = 0;
    while ((ch = getc(input)) != EOF) {
        if (putchar(ch) == EOF) { failed = 1; break; }
        count++;
    }
    if (ferror(input)) failed = 1;
    if (fclose(input) != 0) failed = 1;
    if (!failed && printf("\ncharacters=%lu\n", count) < 0) failed = 1;
    return failed;
}

#include <stdio.h>
#include <string.h>
int main(int argc, char *argv[]) {
    if (argc != 2) return 1;
    char destination[128];
    if (strlen(argv[1]) > sizeof destination - 5) return 1;
    strcpy(destination, argv[1]);
    strcat(destination, ".red");
    FILE *input = fopen(argv[1], "r");
    if (input == NULL) return 1;
    FILE *output = fopen(destination, "w");
    if (output == NULL) {
        fclose(input);
        return 1;
    }
    int phase = 0;
    int ch;
    int failed = 0;
    while ((ch = getc(input)) != EOF) {
        if (phase == 0 && putc(ch, output) == EOF) { failed = 1; break; }
        phase = (phase + 1) % 3;
    }
    if (ferror(input)) failed = 1;
    int input_close = fclose(input);
    int output_close = fclose(output);
    if (input_close != 0 || output_close != 0) failed = 1;
    return failed;
}

#include <stdio.h>
int main(void) {
    FILE *words = fopen("word_notes.txt", "a+");
    if (words == NULL) return 1;
    char word[16];
    int failed = 0;
    while (fscanf(stdin, "%15s", word) == 1 && word[0] != '#') {
        if (fprintf(words, "%s\n", word) < 0) { failed = 1; break; }
    }
    if (ferror(stdin)) failed = 1;
    if (!failed && fseek(words, 0L, SEEK_SET) != 0) failed = 1;
    if (!failed) {
        while (fscanf(words, "%15s", word) == 1) {
            if (puts(word) == EOF) { failed = 1; break; }
        }
        if (ferror(words)) failed = 1;
    }
    if (fclose(words) != 0) failed = 1;
    return failed;
}

#include <stdio.h>
#include <string.h>
int read_name(char *name, int capacity);
int main(void) {
    char name[128];
    puts("FILE NAME:");
    if (read_name(name, 128) != 1 || name[0] == '\0') return 1;
    FILE *input = fopen(name, "rb");
    if (input == NULL) return 1;
    int failed = fseek(input, 0L, SEEK_END) != 0;
    long length = failed ? -1L : ftell(input);
    if (length < 0) failed = 1;
    for (long position = length; !failed && position > 0;) {
        position--;
        if (fseek(input, position, SEEK_SET) != 0) { failed = 1; break; }
        int ch = getc(input);
        if (ch == EOF || putchar(ch) == EOF) { failed = 1; break; }
    }
    if (ferror(input)) failed = 1;
    if (fclose(input) != 0) failed = 1;
    if (!failed && putchar('\n') == EOF) failed = 1;
    return failed;
}
int read_name(char *name, int capacity) {
    if (fgets(name, capacity, stdin) == NULL) return ferror(stdin) ? -2 : 0;
    char *newline = strchr(name, '\n');
    if (newline != NULL) { *newline = '\0'; return 1; }
    int ch = getchar();
    if (ch == '\n') return 1;
    if (ch == EOF) return ferror(stdin) ? -2 : 1;
    while (ch != '\n' && ch != EOF) ch = getchar();
    return ferror(stdin) ? -2 : -1;
}

#include <stdio.h>
#include <string.h>
int read_name(char *name, int capacity);
int copy_blocks(FILE *input, FILE *output);
int main(void) {
    char target_name[128], source_name[128];
    puts("TARGET NAME:");
    if (read_name(target_name, 128) != 1 || target_name[0] == '\0') return 1;
    FILE *target = fopen(target_name, "a+");
    if (target == NULL) return 1;
    if (setvbuf(target, NULL, _IOFBF, 4096) != 0) {
        fclose(target);
        return 1;
    }
    int failed = 0;
    int copied_files = 0;
    while (1) {
        puts("SOURCE NAME (empty to end):");
        int status = read_name(source_name, 128);
        if (status == 0 || (status == 1 && source_name[0] == '\0')) break;
        if (status == -2) { failed = 1; break; }
        if (status < 0) { fputs("NAME TOO LONG\n", stderr); failed = 1; continue; }
        if (strcmp(source_name, target_name) == 0) { fputs("SAME NAME\n", stderr); failed = 1; continue; }
        FILE *source = fopen(source_name, "r");
        if (source == NULL) { fputs("OPEN FAILED\n", stderr); failed = 1; continue; }
        if (setvbuf(source, NULL, _IOFBF, 4096) != 0) {
            if (fclose(source) != 0) failed = 1;
            failed = 1;
            continue;
        }
        int copied = copy_blocks(source, target);
        int closed = fclose(source);
        if (!copied || closed != 0) { failed = 1; break; }
        copied_files++;
    }
    if (fseek(target, 0L, SEEK_SET) != 0) failed = 1;
    else {
        int ch;
        while ((ch = getc(target)) != EOF) {
            if (putchar(ch) == EOF) { failed = 1; break; }
        }
        if (ferror(target)) failed = 1;
    }
    if (fclose(target) != 0) failed = 1;
    if (printf("\ncomplete-files=%d\n", copied_files) < 0) failed = 1;
    return failed;
}
int copy_blocks(FILE *input, FILE *output) {
    char buffer[512];
    size_t count;
    while ((count = fread(buffer, 1, sizeof buffer, input)) > 0) {
        if (fwrite(buffer, 1, count, output) != count) return 0;
    }
    return !ferror(input);
}
int read_name(char *name, int capacity) {
    if (fgets(name, capacity, stdin) == NULL) return ferror(stdin) ? -2 : 0;
    char *newline = strchr(name, '\n');
    if (newline != NULL) { *newline = '\0'; return 1; }
    int ch = getchar();
    if (ch == '\n') return 1;
    if (ch == EOF) return ferror(stdin) ? -2 : 1;
    while (ch != '\n' && ch != EOF) ch = getchar();
    return ferror(stdin) ? -2 : -1;
}

#include <stdio.h>
#include <limits.h>
int main(void) {
    double values[6];
    for (int i = 0; i < 6; i++) values[i] = 10.0 * i + 0.5;
    FILE *output = fopen("measurements.bin", "wb");
    if (output == NULL) return 1;
    int failed = fwrite(values, sizeof values[0], 6, output) != 6;
    if (fclose(output) != 0) failed = 1;
    if (failed) return 1;
    FILE *input = fopen("measurements.bin", "rb");
    if (input == NULL) return 1;
    if (sizeof values[0] > (unsigned long)LONG_MAX) {
        fclose(input);
        return 1;
    }
    long width = (long)sizeof values[0];
    int index;
    while (scanf("%d", &index) == 1 && index >= 0 && index < 6) {
        if ((long)index > LONG_MAX / width) { failed = 1; break; }
        long position = (long)index * width;
        double value;
        if (fseek(input, position, SEEK_SET) != 0 || fread(&value, sizeof value, 1, input) != 1) {
            failed = 1;
            break;
        }
        if (printf("%.1f\n", value) < 0) { failed = 1; break; }
    }
    if (ferror(stdin)) failed = 1;
    if (ferror(input)) failed = 1;
    if (fclose(input) != 0) failed = 1;
    return failed;
}
